#![allow(unused)]
use vstd::prelude::*;

verus! {
    /// Given two vectors of i8 of equal length, produce a boolean vector `res` of the same length
    /// such that for each index `i`, `res[i] == (a[i] < b[i])`.
    fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool>
        requires
            a.len() == b.len(),
        ensures
            |res: Vec<bool>|
                // result has the same length as inputs
                res.len() == a.len() &&
                // for every index i, res[i] is true exactly when a[i] < b[i]
                forall(|i: usize| i < a.len() ==> res[i] == (a[i] < b[i]))
    {
        let mut res: Vec<bool> = Vec::new();
        let mut i: usize = 0;

        // Loop over all indices
        while i < a.len() {
            // Invariants to maintain correctness
            invariant i <= a.len();
            invariant res.len() == i;
            invariant forall(|j: usize| j < i ==> res[j] == (a[j] < b[j]));
            // Decrease measure for termination
            decreases a.len() - i;

            // Push the comparison result for position `i`
            res.push(a[i] < b[i]);
            i += 1;
        }

        res
    }
}